# Analyze each color shape as a rectangle
# Let me identify all rectangular outlines and their dimensions

def find_rectangles(grid):
    """Find all rectangular outlines in the grid."""
    rectangles = {}
    colors = set()

    # Get all non-zero values
    for row in grid:
        for val in row:
            if val > 0:
                colors.add(val)

    for color in colors:
        # Find bounding box
        positions = []
        for r, row in enumerate(grid):
            for c, val in enumerate(row):
                if val == color:
                    positions.append((r, c))

        if not positions:
            continue

        min_r = min(p[0] for p in positions)
        max_r = max(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_c = max(p[1] for p in positions)

        height = max_r - min_r + 1
        width = max_c - min_c + 1

        # Check if this forms a rectangular outline
        is_outline = True
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if (r, c) in positions:
                    # Should be on edge
                    if not (r == min_r or r == max_r or c == min_c or c == max_c):
                        is_outline = False
                        break
        else:
            if not is_outline:
                continue

        # Count corner pixels
        corners = 0
        corner_reqs = [
            (min_r, min_c), (min_r, max_c),
            (max_r, min_c), (max_r, max_c)
        ]
        for cr in corner_reqs:
            if cr in positions:
                corners += 1

        rectangles[color] = (min_r, min_c, height, width, corners)

    return rectangles

rectangles = find_rectangles(test_input)
print("Rectangular outlines found:")
for color, (r, c, h, w, corners) in rectangles.items():
    print(f"  Color {color}: top-left=({r},{c}), size={h}x{w}, corners={corners}")

